private static NewReservation readNewReservation(Context ctx) {
    CreateReservationRequest body;
    try {
        body = ctx.bodyAsClass(CreateReservationRequest.class);
    } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
        throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
    }
    if (body == null
            || body.roomNumber() == null
            || isBlank(body.guestName())
            || isBlank(body.guestEmail())
            || body.checkIn() == null
            || body.checkOut() == null
            || body.guests() == null
            || body.ratePlan() == null) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
    }

    boolean hasCpf = !isBlank(body.guestCpf());
    boolean hasCompany = !isBlank(body.companyCnpj()) && !isBlank(body.companyName());
    boolean hasPassport = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());

    if ((hasCpf && hasCompany) || (hasCpf && hasPassport) || (hasCompany && hasPassport)) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "only one type of identification is allowed");
    }
    if (!hasCpf && !hasCompany && !hasPassport) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "guest identification is required");
    }
    if (hasCompany && (isBlank(body.companyCnpj()) || isBlank(body.companyName()))) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "company reservations require both CNPJ and name");
    }
    if (hasPassport && (isBlank(body.guestPassport()) || isBlank(body.guestCountry()))) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "passport reservations require both passport and country");
    }

    Guest guest;
    if (hasCpf) {
        guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
    } else if (hasCompany) {
        guest = new Guest(body.guestName(), body.guestEmail(), body.companyCnpj(), body.companyName());
    } else {
        guest = Guest.withPassport(null, body.guestName(), body.guestEmail(), body.guestPassport(), body.guestCountry());
    }

    return new NewReservation(
            body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
}

